"""Source acquisition, deliberate target marking and the existing review controls."""
import json
from pathlib import Path
from .semantic_reader import AXES
from .semantic_controls import SCRIPT


def page():
    from ..application_shell import wrap
    result = HTML.replace('__AXES__',json.dumps({k:list(v) for k,v in AXES.items()})).replace('__HELPERS__',SCRIPT).replace('__COHORTS__',(Path(__file__).parent/'assets/learning_cohorts.js').read_text()).replace('__TYPED__',(Path(__file__).parent/'assets/typed_learning.js').read_text())
    return wrap(result,active='review',title='Source review')


HTML=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Agere · Source learning</title>
<style>:root{color-scheme:light;font-family:ui-sans-serif,system-ui;background:#faf9f6;color:#292631}*{box-sizing:border-box}body{margin:0}main{max-width:1120px;margin:auto;padding:40px 24px}a{color:#6d4ab0}h1{font-size:46px;letter-spacing:-1.5px;font-weight:500;margin:28px 0 18px}h2,h3{font-weight:500}p{line-height:1.6}.pill{color:#6b548b;font:12px ui-monospace,monospace;letter-spacing:2px}.meta{color:#655e71;font-size:13px}.missing{color:#805b24;font-size:13px}.source,article{border:1px solid #e3deeb;background:#ffffff;border-radius:12px;padding:20px;margin:18px 0}blockquote{white-space:pre-wrap;border-left:2px solid #a48acb;margin:20px 0;padding:10px 20px;line-height:1.7;max-height:440px;overflow:auto}mark{background:#eee7f8;color:#35234f}button,select,input,textarea{font:inherit;background:#ffffff;color:#292631;border:1px solid #b2a3c8;border-radius:7px;padding:10px;min-height:42px;margin:5px 8px 5px 0;max-width:100%}button{cursor:pointer}button:disabled{opacity:.5}label{display:inline-block;margin:5px}textarea{display:block;width:100%;height:85px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}summary{cursor:pointer;color:#61418f}.stats{display:flex;gap:34px;flex-wrap:wrap;margin:26px 0}.stats strong{display:block;font-size:32px;font-weight:500;color:#eee7f8}.controls{display:flex;gap:8px;flex-wrap:wrap}.tag{font:12px ui-monospace,monospace;text-transform:uppercase;color:#6b548b}.reader-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}.reader-grid .source{margin:0}.target-editor{border-top:1px solid #e3deeb;margin-top:18px;padding-top:16px}.typed-item{display:grid;grid-template-columns:1fr auto;gap:4px 16px;border-bottom:1px solid #e3deeb;padding:18px 0}.typed-item p{margin:0}.typed-item button{grid-column:2;grid-row:1 / 3;align-self:center}.typed-item .meta{grid-column:1}.stats strong{color:#61418f}input[type=checkbox]{min-height:auto;accent-color:#7752b9}#typed-detail select{display:block;width:100%}#typed-detail{scroll-margin-top:20px}#typed-list{max-height:480px;overflow:auto;padding-right:12px;overscroll-behavior:contain}@media(max-width:600px){main{padding:24px 16px}h1{font-size:34px}.typed-item{display:block}.typed-item button{margin-top:10px}}:focus-visible{outline:3px solid #9270c6;outline-offset:3px}</style>
<main><nav><a href="/stack">← Stack workbench</a> · <a href="/semantics">Statement readers</a> · <a href="/programs">Program workspace</a></nav><p class="pill">AGERE / SOURCE LEARNING / SYNTHETIC WORKSPACE</p><h1>Teach the parts<br>the record makes difficult.</h1><p>Source passages selected for learning: difficult interpretations, a sample chosen independently of model scores, and received text with no extracted concept. Protected acquisition training families supply this queue; reserved and outer evaluation families stay outside it.</p><div id="stats" class="stats"></div><p class="meta">Machine suggestions remain separate from your source review. A missed annotation is an audit candidate, not proof that retrieval failed or care was missed.</p><div id="method"></div><article><h2>From source readings to local skills</h2><p>Native readers share exact source targets. Small classifiers can learn to imitate a declared teacher; they remain separate from reviewed labels and current clinical facts.</p><button id="distillation">Inspect native acquisition and training provenance</button><div id="distillation-results" aria-live="polite"></div><p><a href="/semantics">Inspect trained shadow readers →</a></p></article>
<article id="typed-review"><h2>Review how an answer was read</h2><p>Compare a recorded reading with its original document. Confirm it, correct it, or keep it unresolved. You choose whether a reviewed example may be used in future development training.</p><p id="typed-model-status" class="meta" role="status"></p><p id="typed-status" role="status" aria-live="polite"></p><div id="typed-list" tabindex="0" role="region" aria-label="Saved document readings"></div><div class="controls"><button id="typed-previous">Previous readings</button><button id="typed-next">More readings</button></div><div id="typed-detail" aria-live="polite"></div></article><article><h2>Current warehouse qualification</h2><div id="current-learning" aria-live="polite"></div><div id="design-qualification" aria-live="polite"></div></article><article><h2>Additional source-learning cohorts</h2><p class="meta">Independent acquisition manifests preserve the current review queue. Prior development partitions remain constraints.</p><div id="learning-cohorts" aria-live="polite"></div></article><article><h2>Question-triggered source tasks</h2><p class="meta">A selected development lane, separate from the fixed audit sample. Source targets remain unlabeled until explicitly reviewed.</p><div id="question-tasks"></div></article><form id="filters" class="controls"><label>Review lane <select id="lane"><option value="">All lanes</option></select></label><label>Source <select id="stream"><option value="">All source streams</option></select></label><button>Load source queue</button></form><p id="status" role="status" aria-live="polite"></p><div id="items"></div><div class="controls"><button id="previous">Previous</button><button id="next">Next</button></div></main>
<script>const SEMANTIC_AXES=__AXES__;const $=id=>document.getElementById(id);const N=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e};const human=s=>s.replaceAll('_',' ');function details(title,data){const e=N('details');e.append(N('summary',title),N('pre',JSON.stringify(data,null,2)));return e}
__HELPERS__
__COHORTS__
let offset=0,initialized=false;
function targetEditor(box,item){
 const wrap=N('div',undefined,'target-editor');wrap.append(N('h3','Mark another phrase for interpretation'),N('p','Copy an exact phrase from this received field and name the concept it expresses. Marking creates a source task; it does not assign an interpretation label.','meta'));
 const quote=N('input');quote.placeholder='Exact phrase from the source';quote.setAttribute('aria-label','Exact source phrase');quote.maxLength=2000;
 const concept=N('input');concept.placeholder='Concept, such as financial hardship';concept.setAttribute('aria-label','Target concept');concept.maxLength=150;
 const label=N('label','Occurrence (first = 1) '),occurrence=N('input');occurrence.type='number';occurrence.min='1';occurrence.max='500';occurrence.value='1';occurrence.setAttribute('aria-label','Source phrase occurrence');label.append(occurrence);
 const save=N('button','Mark source phrase'),message=N('p','','meta');save.onclick=async()=>{save.disabled=true;try{const r=await semanticFetch('/api/stack/learning-queue/target',{item_id:item.id,quote:quote.value,concept:concept.value,occurrence:Number(occurrence.value)-1});message.textContent='Exact phrase marked. '+r.quote_occurrences+' matching occurrence(s) exist in this source. No interpretation label was created.';const task=N('div',undefined,'source');task.append(N('h3',r.target.concept),N('blockquote',r.quote));learningReaders(task,r.target);wrap.append(task)}catch(e){message.textContent=String(e)}finally{save.disabled=false}};wrap.append(quote,concept,label,save,message);box.append(wrap);
}
async function inspectSource(box,item,button){button.disabled=true;try{
 const r=await semanticFetch('/api/stack/learning-queue/item?id='+item.id),source=N('blockquote');const t=item.target,characters=Array.from(r.text);
 if(t&&t.end<=characters.length)source.append(document.createTextNode(characters.slice(0,t.start).join('')),N('mark',characters.slice(t.start,t.end).join('')),document.createTextNode(characters.slice(t.end).join('')));else source.textContent=r.text;
 box.append(N('h3','Received source text'),source,N('p',r.text_complete?'Complete received text field · source hash verified':'Source display capped at 100,000 characters; full received text has '+r.source_text_characters+' characters.','meta'));
 for(const target of r.target_options){const task=N('div',undefined,'source');task.append(N('h3',target.concept));learningReaders(task,target);box.append(task)}
 const comparisons=N('div',undefined,'reader-grid');for(const reading of r.readings){const cell=N('div',undefined,'source');cell.append(N('h3',reading.provider),N('p',Object.entries(reading.reading.labels).map(([a,v])=>a+': '+human(v)).join(' · ')),N('p',reading.reviews.length?'Saved source review available':'Unreviewed model proposal','meta'));const review=N('button','Inspect '+reading.provider+' interpretation');review.onclick=()=>{review.disabled=true;renderSemantic(cell,reading)};cell.append(review);comparisons.append(cell)}if(r.readings.length)box.append(N('h3','Readers on this source'),comparisons);
 for(const attempt of r.suggestion_attempts||[])if(attempt.error)box.append(N('p',attempt.provider+' · '+human(attempt.failure_kind)+': '+attempt.error,'missing'));
 targetEditor(box,item);box.append(details('Selection, source provenance and learning limits',r));
}catch(e){box.append(N('p',String(e)));button.disabled=false}}
async function load(){try{$('status').textContent='Loading the protected source queue…';const r=await semanticFetch('/api/stack/learning-queue?lane='+encodeURIComponent($('lane').value)+'&stream='+encodeURIComponent($('stream').value)+'&offset='+offset);if(r.status==='not_attached'){$('status').textContent='No additional source queue is attached. Saved answer readings remain available above.';$('previous').disabled=true;$('next').disabled=true;return}if(!initialized){for(const lane of Object.keys(r.run.selection_counts))$('lane').add(new Option(human(lane),lane));for(const stream of Object.keys(r.run.selected_streams))$('stream').add(new Option(human(stream),stream));for(const [name,value] of [['Source tasks',r.run.selected],['Patient families',r.run.selected_families],['Without annotations',r.run.selection_counts.extraction_audit||0],['Reviewed labels auto-created',r.run.training_labels_created]]){const c=N('div');c.append(N('strong',Number(value).toLocaleString()),N('span',name,'meta'));$('stats').append(c)}$('method').append(details('How these sources were selected',r.run));initialized=true}
 $('items').replaceChildren();for(const item of r.rows){const box=N('article');box.append(N('p',human(item.selection_lane),'tag'),N('h2',item.target?item.target.concept:'Received text without an extracted concept'),N('p',item.patient_id+' · '+human(item.stream)+' · '+item.field,'meta'),N('p',item.target?item.saved_readings+' saved reader proposal(s). Inspect the source to compare or correct them.':'Inspect this field to decide whether there is a meaningful proposition to mark.'));if(item.priority_reasons.length)box.append(N('p',item.priority_reasons.map(human).join(' · '),'meta'));const b=N('button','Inspect this source');b.onclick=()=>inspectSource(box,item,b);box.append(b);$('items').append(box)}$('status').textContent=r.total+' tasks match · every task is in the protected acquisition training partition · source bindings rechecked on inspection.';$('previous').disabled=offset===0;$('next').disabled=offset+r.limit>=r.total;
}catch(e){$('status').textContent=String(e)}}
$('distillation').onclick=async()=>{const box=$('distillation-results');try{const r=await semanticFetch('/api/stack/source-distillation');box.replaceChildren(N('p',r.status==='not_attached'?'No source distillation plan attached.':r.target_count+' exact source targets · '+r.unassessed_source_fields+' unassessed fields · teacher: '+r.teacher));if(r.providers)for(const [provider,v] of Object.entries(r.providers))box.append(N('p',provider+': '+v.successful_readings+' completed readings · '+v.pending+' unattempted targets'),details(provider+' execution accounting',v));if(r.limits)for(const limit of r.limits)box.append(N('p',limit,'meta'));box.append(details('Source, partitions and paired disagreements',r))}catch(e){box.textContent=String(e)}};
async function openQuestionTask(key,box){try{const r=await semanticFetch('/api/stack/question-learning?id='+encodeURIComponent(key));box.replaceChildren(N('h3',r.target.concept),N('p',r.original_question),N('blockquote',r.context.text),N('p','Target: '+r.context.target_quote+' · '+human(r.source_structure.role),'meta'),N('p',r.qualification.student_input_contract_ready?'Exact complete context is ready for optional readers. No qualified model or reviewed label is established.':r.qualification.student_input_rejection,'missing'));if(r.machine_acquisition?.length)box.append(N('p','Target selected from a machine phrase proposal; no human source review or training label is implied.','missing'),details('Machine acquisition receipts',r.machine_acquisition));learningReaders(box,r.target);for(const reading of r.readings)renderSemantic(box,reading);box.append(details('Acquisition eligibility, source roles and exact question provenance',r))}catch(e){box.textContent=String(e)}}
async function currentLearning(){try{const r=await semanticFetch('/api/stack/current-learning'),box=$('current-learning');box.replaceChildren(N('p',r.status==='current'?r.queue.selected+' current-source audit/priority tasks · '+r.source_reviews.distinct_reviewed_occurrences+' reviewed occurrences · legacy attached readers: '+r.attached_students.status+'. Additional cohorts appear below.':'No current source-learning queue attached.'));if(r.status==='current'){box.append(N('p',r.qualification_boundary,'missing'),details('Partitions, current review evidence and model qualification',r));const tasks=$('question-tasks');for(const row of r.question_tasks.rows){const item=N('div',undefined,'source');if(row.status==='stale')item.append(N('p','Stale source task: '+row.reason,'missing'));else{item.append(N('p',row.original_question),N('p',row.target.concept+' · '+row.target.patient_id,'meta'));const b=N('button','Inspect question source task');b.onclick=()=>openQuestionTask(row.id,item);item.append(b)}tasks.append(item)}if(!r.question_tasks.total)tasks.append(N('p','Create a task from candidate passages on an unresolved question.'));const key=new URLSearchParams(location.search).get('task');if(key){const selected=N('div',undefined,'source');tasks.prepend(selected);await openQuestionTask(key,selected)}}}catch(e){$('current-learning').textContent=String(e)}}
async function designQualification(){try{const r=await semanticFetch('/api/stack/learning-qualification'),box=$('design-qualification');if(r.status==='not_attached'){box.append(N('p','No fixed development design attached.','meta'));return}box.append(N('h3','Original attached audit design'),N('p',r.counts.train+' fitting targets · '+r.counts.calibration+' calibration targets · '+r.counts.validation+' development validation targets'),N('p',r.recommended_next_step,'missing'));for(const reason of r.structural_failures)box.append(N('p',human(reason.code)+': '+reason.observed+' / '+reason.minimum+' required. '+reason.detail,'meta'));box.append(details('Predeclared design and unchanged qualification policy',r))}catch(e){$('design-qualification').textContent=String(e)}}
__TYPED__
currentLearning();designQualification();
$('filters').onsubmit=e=>{e.preventDefault();offset=0;load()};$('previous').onclick=()=>{offset=Math.max(0,offset-12);load()};$('next').onclick=()=>{offset+=12;load()};load();</script></html>'''
